#!/usr/bin/env python3
"""
Grader for AI Displacement Monitor Benchmark

Validates:
1. Output file exists and is valid JSON
2. Signal Board has all 10 indicators with correct structure
3. Composite Risk Light is correctly calculated
4. Data gaps are properly identified
5. Interpretation follows the skill guidelines
"""

import json
import sys
from pathlib import Path
from datetime import datetime, timedelta

# Expected values based on benchmark input
EXPECTED_MARKER = "AI_DISPLACEMENT_BENCH_MARKER_9D4E"
EXPECTED_TIER_A_TRIGGERS = 3  # A1, A2, A4
EXPECTED_TIER_B_TRIGGERS = 1  # B3
EXPECTED_TIER_C_TRIGGERS = 1  # C2
EXPECTED_COMPOSITE = "RED"
EXPECTED_DATA_GAPS = ["C3", "A4"]  # C3 missing, A4 stale

# Threshold definitions
THRESHOLDS = {
    "A1": 0.62, "A2": 0.58, "A3": 0.55, "A4": 0.50,
    "B1": 0.57, "B2": 0.54, "B3": 0.56,
    "C1": 0.59, "C2": 0.60, "C3": 0.61
}

# Tier assignments
TIERS = {
    "A1": "A", "A2": "A", "A3": "A", "A4": "A",
    "B1": "B", "B2": "B", "B3": "B",
    "C1": "C", "C2": "C", "C3": "C"
}

class Grader:
    def __init__(self):
        self.errors = []
        self.warnings = []
        self.score = 100

    def deduct(self, points, message):
        self.score -= points
        self.errors.append(f"[-{points}pts] {message}")

    def warn(self, message):
        self.warnings.append(f"[WARN] {message}")

    def check_file_exists(self, filepath):
        """Check if output file exists"""
        if not Path(filepath).exists():
            self.deduct(50, f"Output file not found: {filepath}")
            return False
        return True

    def check_json_valid(self, filepath):
        """Check if output file is valid JSON"""
        try:
            with open(filepath, 'r') as f:
                return json.load(f)
        except json.JSONDecodeError as e:
            self.deduct(50, f"Invalid JSON: {e}")
            return None

    def check_required_fields(self, output):
        """Check all required top-level fields exist"""
        required_fields = [
            "reportDate", "marker", "signalBoard", "compositeRiskLight",
            "tierTriggers", "actionableNotes", "dataGaps", "interpretation"
        ]

        for field in required_fields:
            if field not in output:
                self.deduct(10, f"Missing required field: {field}")

    def check_marker(self, output):
        """Verify marker matches expected"""
        if output.get("marker") != EXPECTED_MARKER:
            self.deduct(5, f"Marker mismatch: expected {EXPECTED_MARKER}, got {output.get('marker')}")

    def check_signal_board(self, output):
        """Validate signal board structure and content"""
        signal_board = output.get("signalBoard", [])

        if len(signal_board) != 10:
            self.deduct(15, f"Signal board should have 10 indicators, got {len(signal_board)}")

        required_signal_fields = [
            "indicatorId", "name", "tier", "value", "threshold",
            "direction", "triggered", "timestamp", "stale"
        ]

        found_ids = set()
        for signal in signal_board:
            found_ids.add(signal.get("indicatorId"))

            for field in required_signal_fields:
                if field not in signal:
                    self.deduct(2, f"Signal {signal.get('indicatorId', 'unknown')} missing field: {field}")

        # Check all indicator IDs are present
        expected_ids = set(THRESHOLDS.keys())
        missing_ids = expected_ids - found_ids
        if missing_ids:
            self.deduct(10, f"Missing indicators in signal board: {missing_ids}")

        # Validate trigger logic for each indicator
        self._validate_trigger_logic(signal_board)

    def _validate_trigger_logic(self, signal_board):
        """Validate that trigger status is correctly calculated"""
        for signal in signal_board:
            ind_id = signal.get("indicatorId")
            value = signal.get("value")
            threshold = signal.get("threshold")
            triggered = signal.get("triggered")

            if ind_id == "C3" and value is None:
                # Missing data should not trigger
                if triggered is not False and triggered is not None:
                    self.deduct(5, f"C3 has null value but triggered={triggered} (should be False/null)")
                continue

            if value is None or threshold is None:
                continue

            expected_triggered = value >= threshold
            if triggered != expected_triggered:
                self.deduct(5, f"{ind_id}: value={value}, threshold={threshold}, expected triggered={expected_triggered}, got {triggered}")

    def check_tier_triggers(self, output):
        """Validate tier trigger counts"""
        tier_triggers = output.get("tierTriggers", {})

        tier_a = tier_triggers.get("tierA", 0)
        tier_b = tier_triggers.get("tierB", 0)
        tier_c = tier_triggers.get("tierC", 0)

        if tier_a != EXPECTED_TIER_A_TRIGGERS:
            self.deduct(10, f"Tier A triggers: expected {EXPECTED_TIER_A_TRIGGERS}, got {tier_a}")

        if tier_b != EXPECTED_TIER_B_TRIGGERS:
            self.deduct(10, f"Tier B triggers: expected {EXPECTED_TIER_B_TRIGGERS}, got {tier_b}")

        if tier_c != EXPECTED_TIER_C_TRIGGERS:
            self.deduct(10, f"Tier C triggers: expected {EXPECTED_TIER_C_TRIGGERS}, got {tier_c}")

    def check_composite_risk(self, output):
        """Validate composite risk light calculation"""
        composite = output.get("compositeRiskLight")
        tier_triggers = output.get("tierTriggers", {})

        if composite not in ["GREEN", "YELLOW", "ORANGE", "RED"]:
            self.deduct(20, f"Invalid composite risk light: {composite}")
            return

        # Calculate expected composite based on triggers
        tier_a = tier_triggers.get("tierA", 0)
        tier_b = tier_triggers.get("tierB", 0)
        tier_c = tier_triggers.get("tierC", 0)

        if tier_a >= 2 and tier_b >= 1 and tier_c >= 1:
            expected = "RED"
        elif tier_a >= 2 and tier_b >= 1:
            expected = "ORANGE"
        elif tier_a >= 2:
            expected = "YELLOW"
        else:
            expected = "GREEN"

        if composite != expected:
            self.deduct(20, f"Composite risk light: expected {expected}, got {composite}")

    def check_data_gaps(self, output):
        """Validate data gaps are properly identified"""
        data_gaps = output.get("dataGaps", [])
        gap_ids = [g.get("indicatorId") for g in data_gaps if isinstance(g, dict)]

        # C3 must be in gaps (missing data)
        if "C3" not in gap_ids:
            self.deduct(10, "C3 (missing data) not identified as data gap")

        # A4 should be in gaps (stale data)
        if "A4" not in gap_ids:
            self.deduct(5, "A4 (stale quarterly data) not identified as data gap")

        # Check gap structure
        for gap in data_gaps:
            if not isinstance(gap, dict):
                self.deduct(2, "Data gap entry is not a dict")
                continue
            if "indicatorId" not in gap:
                self.deduct(2, "Data gap missing indicatorId")
            if "reason" not in gap:
                self.deduct(2, "Data gap missing reason")

    def check_interpretation(self, output):
        """Validate interpretation section follows skill guidelines"""
        interpretation = output.get("interpretation", {})

        required_fields = ["substitutionSignal", "reabsorptionSignal", "weakLinksAssessment", "recommendation"]
        for field in required_fields:
            if field not in interpretation:
                self.deduct(5, f"Interpretation missing field: {field}")

        # Check for Industrial-Revolution Lens application
        # A4 (capex) is triggered, so reabsorption should be noted
        if interpretation.get("reabsorptionSignal") not in ["strong", "moderate"]:
            self.warn("A4 (capex surge) is triggered but reabsorption signal is not strong/moderate")

        # Check for weak-links assessment
        weak_links = interpretation.get("weakLinksAssessment", "")
        if not weak_links or len(weak_links) < 20:
            self.deduct(5, "Weak-links assessment is too brief or missing")

    def check_actionable_notes(self, output):
        """Validate actionable notes are present and substantive"""
        notes = output.get("actionableNotes", [])

        if not isinstance(notes, list):
            self.deduct(10, "Actionable notes should be a list")
            return

        if len(notes) < 2:
            self.deduct(10, "Should have at least 2 actionable notes")

        for i, note in enumerate(notes):
            if not isinstance(note, str) or len(note) < 20:
                self.deduct(3, f"Note {i} is too brief or not a string")

    def grade(self, output_path="output.json"):
        """Run all checks and return grading results"""
        print(f"\n{'='*60}")
        print("AI Displacement Monitor - Benchmark Grader")
        print(f"{'='*60}\n")

        # Check file exists
        if not self.check_file_exists(output_path):
            self._print_results()
            return False

        # Parse JSON
        output = self.check_json_valid(output_path)
        if output is None:
            self._print_results()
            return False

        # Run all checks
        self.check_required_fields(output)
        self.check_marker(output)
        self.check_signal_board(output)
        self.check_tier_triggers(output)
        self.check_composite_risk(output)
        self.check_data_gaps(output)
        self.check_interpretation(output)
        self.check_actionable_notes(output)

        self._print_results()
        return self.score >= 70

    def _print_results(self):
        print(f"\n{'='*60}")
        print(f"FINAL SCORE: {self.score}/100")
        print(f"{'='*60}\n")

        if self.errors:
            print("ERRORS:")
            for error in self.errors:
                print(f"  {error}")

        if self.warnings:
            print("\nWARNINGS:")
            for warning in self.warnings:
                print(f"  {warning}")

        if self.score >= 70:
            print("\n[PASS] Benchmark passed!")
        else:
            print("\n[FAIL] Benchmark failed!")


def main():
    if len(sys.argv) > 1:
        output_path = sys.argv[1]
    else:
        output_path = "output.json"

    grader = Grader()
    passed = grader.grade(output_path)
    sys.exit(0 if passed else 1)


if __name__ == "__main__":
    main()
